with RecursiveWelInfo as (
    select
        u.Id as UserId,
        u.DisplayName as Username,
        sum(case when p.PostTypeId = 1 then 1 else 0 end) as TotalQuestions,
        sum(case when p.PostTypeId = 2 then 1 else 0 end) as TotalAnswers,
        coalesce(sum(v.UpVoteCnt),0) as UserUpVotes,
        row_number() over (partition by u.Id order by max(p.CreationDate) desc nulls last) as UserRowClustering
